import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import java.util.List;
import java.util.Map;

@Mixin(LivingEntity.class)
public abstract class LivingEntityMixin {

    @Inject(method = "onEffectRemoved", at = @At(value = "HEAD"))
    public void irons_spellbooks$onEffectRemoved(MobEffectInstance effectInstance, CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level.isClientSide) {
            if (effectInstance.getEffect().value() instanceof IMobEffectEndCallback mobEffect) {
                mobEffect.onEffectRemoved(self, effectInstance.getAmplifier());
            }
            if (effectInstance.getEffect().value() instanceof ISyncedMobEffect && self.level.getChunkSource() instanceof ServerChunkCache serverChunk) {
                serverChunk.broadcast(self, new ClientboundRemoveMobEffectPacket(self.getId(), effectInstance.getEffect()));
            }
        }
    }

    @Inject(method = "onEffectUpdated", at = @At(value = "HEAD"))
    public void irons_spellbooks$onEffectUpdated(MobEffectInstance effectInstance, boolean forced, Entity entity, CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level.isClientSide) {
            if (effectInstance.getEffect().value() instanceof ISyncedMobEffect && self.level.getChunkSource() instanceof ServerChunkCache serverChunk) {
                serverChunk.broadcast(self, new ClientboundUpdateMobEffectPacket(self.getId(), effectInstance, false));
            }
        }
    }

    @Inject(method = "onEffectAdded", at = @At(value = "HEAD"))
    public void irons_spellbooks$onEffectAdded(MobEffectInstance effectInstance, Entity entity, CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level.isClientSide) {
            if (effectInstance.getEffect().value() instanceof ISyncedMobEffect && self.level.getChunkSource() instanceof ServerChunkCache serverChunk) {
                serverChunk.broadcast(self, new ClientboundUpdateMobEffectPacket(self.getId(), effectInstance, false));
            }
        }
    }

    @Inject(method = "updateInvisibilityStatus", at = @At(value = "TAIL"))
    public void irons_spellbooks$updateInvisibilityStatus(CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (self.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY))
            self.setInvisible(true);
    }

    @Inject(method = "isCurrentlyGlowing", at = @At(value = "HEAD"), cancellable = true)
    public void irons_spellbooks$isCurrentlyGlowing(CallbackInfoReturnable<Boolean> cir) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level.isClientSide() && self.hasEffect(MobEffectRegistry.GUIDING_BOLT)) {
            cir.setReturnValue(true);
        }
    }

    @Inject(method = "hurt", at = @At("RETURN"))
    public void irons_spellbooks$changeSummonHurtCredit(DamageSource damageSource, float amount, CallbackInfoReturnable<Boolean> cir) {
        IMagicSummon fromSummon = damageSource.getDirectEntity() instanceof IMagicSummon summon ? summon : damageSource.getEntity() instanceof IMagicSummon summon ? summon : null;
        if (fromSummon instanceof LivingEntity livingSummon) {
            ((LivingEntity) (Object) this).setLastHurtByMob(livingSummon);
        }
    }

    @Shadow
    abstract ItemStack getLastHandItem(EquipmentSlot pSlot);

    @Unique
    private static final List<EquipmentSlot> handSlots = List.of(EquipmentSlot.OFFHAND, EquipmentSlot.MAINHAND);

    // The equipment change event fires 5 lines too early for this to have been able to be done via events
    @Inject(method = "collectEquipmentChanges", at = @At(value = "RETURN"))
    public void handleEquipmentChanges(CallbackInfoReturnable<Map<EquipmentSlot, ItemStack>> cir) {
        // Last hand items are accurate at this point
        // Mainhand assigning/removing is handled by minecraft. All we are doing is fudging offhand handling
        // The return of this function is a map of equipmentslots to itemstacks, of itemstacks who have been changed
        var changedEquipment = cir.getReturnValue();
        if (changedEquipment == null) {
            return;
        }
        LivingEntity self = (LivingEntity) (Object) this;
        ItemStack toStack = changedEquipment.get(EquipmentSlot.MAINHAND);
        if (toStack == null) {
            // If this stack was not changed, continue
            return;
        }
        ItemStack fromStack = getLastHandItem(EquipmentSlot.MAINHAND);
        ItemStack offhandStack = self.getOffhandItem();
        //offhand swap
        if (fromStack == offhandStack) {
            return;
        }
        //Do we even care
        if (!offhandStack.isEmpty() && offhandStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
            //did we equip a multihand item? (hide offhand)
            if (toStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
                if (!toStack.isEmpty()) {
                    self.getAttributes().removeAttributeModifiers(filterApplicableAttributes(offhandStack.getAttributeModifiers()));
                }
            }
            //did we unequip a multihand item? (reveal offhand)
            else if (fromStack.has(ComponentRegistry.MULTIHAND_WEAPON)) {
                if (!offhandStack.isEmpty()) {
                    self.getAttributes().addTransientAttributeModifiers(filterApplicableAttributes(offhandStack.getAttributeModifiers()));
                }
            }
        }
    }

    @Unique
    private static Multimap<Holder<Attribute>, AttributeModifier> filterApplicableAttributes(ItemAttributeModifiers modifiers) {
        var list = modifiers.modifiers().stream().filter(entry -> entry.slot() == EquipmentSlotGroup.MAINHAND).toList();
        Multimap<Holder<Attribute>, AttributeModifier> map = HashMultimap.create();
        for (ItemAttributeModifiers.Entry entry : list) {
            var predicate = ServerConfigs.APPLY_ALL_MULTIHAND_ATTRIBUTES.get() ? Utils.NON_BASE_ATTRIBUTES : Utils.ONLY_MAGIC_ATTRIBUTES;
            if (predicate.test(entry.attribute())) {
                map.put(entry.attribute(), entry.modifier());
            }
        }
        return map;
    }

}

package io.redspace.ironsspellbooks.network.particles;

import io.redspace.ironsspellbooks.IronsSpellbooks;
import io.redspace.ironsspellbooks.player.ClientSpellCastHelper;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.network.handling.IPayloadContext;

public class FieryExplosionParticlesPacket implements CustomPacketPayload {
    private final Vec3 pos1;
    private final float radius;
    public static final CustomPacketPayload.Type<FieryExplosionParticlesPacket> TYPE = new CustomPacketPayload.Type<>(ResourceLocation.fromNamespaceAndPath(IronsSpellbooks.MODID, "fiery_explosion_particles"));
    public static final StreamCodec<RegistryFriendlyByteBuf, FieryExplosionParticlesPacket> STREAM_CODEC = CustomPacketPayload.codec(FieryExplosionParticlesPacket::write, FieryExplosionParticlesPacket::new);

    public FieryExplosionParticlesPacket(Vec3 pos1, float radius) {
        this.pos1 = pos1;
        this.radius = radius;
    }

    public FieryExplosionParticlesPacket(FriendlyByteBuf buf) {
        pos1 = buf.readVec3();
        radius = buf.readFloat();
    }

    public void write(FriendlyByteBuf buf) {
        buf.writeVec3(pos1);
        buf.writeFloat(radius);
    }

    public static void handle(FieryExplosionParticlesPacket packet, IPayloadContext context) {
        context.enqueueWork(() -> {
            ClientSpellCastHelper.handleClientboundFieryExplosion(packet.pos1, packet.radius);
        });
    }

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }
}

    public static void onBeforeDamageTaken(LivingDamageEvent.Pre event) {
        var livingEntity = event.getEntity();
        if (livingEntity instanceof IMagicEntity || livingEntity instanceof ServerPlayer) {
            var playerMagicData = MagicData.getPlayerMagicData(livingEntity);
            if (livingEntity.hasEffect(MobEffectRegistry.HEARTSTOP)) {
                playerMagicData.getSyncedData().addHeartstopDamage(event.getOriginalDamage() * .5f);
                event.setNewDamage(0);
            }
        }
        if (event.getSource().is(ISSDamageTypes.FIRE_MAGIC) && event.getSource().getEntity() instanceof LivingEntity livingAttacker) {
            if (livingAttacker.getItemBySlot(EquipmentSlot.CHEST).is(ItemRegistry.INFERNAL_SORCERER_CHESTPLATE) && (!(livingAttacker instanceof Player player) || !player.getCooldowns().isOnCooldown(ItemRegistry.INFERNAL_SORCERER_CHESTPLATE.get()))) {
                ImmolateEffect.addImmolateStack(livingEntity, livingAttacker);
//                if (livingAttacker instanceof Player player) {
//                    player.getCooldowns().addCooldown(ItemRegistry.INFERNAL_SORCERER_CHESTPLATE.get(), Utils.applyCooldownReduction(InfernalSorcererArmorItem.COOLDOWN_TICKS, player));
//                }
            }
        }
    }

public static void onPlayerStartTrackingEntity(PlayerEvent.StartTracking event) {
    if (event.getEntity() instanceof ServerPlayer serverPlayerRecipient) {
        if (event.getTarget() instanceof LivingEntity livingEntity) {
            for (var inst : livingEntity.getActiveEffects()) {
                if (inst.getEffect().value() instanceof ISyncedMobEffect) {
                    serverPlayerRecipient.connection.send(new ClientboundUpdateMobEffectPacket(livingEntity.getId(), inst, false));
                }
            }
        }
    }
}

public static void onClientEntityTick(EntityTickEvent.Pre event) {
    if (event.getEntity() instanceof LivingEntity livingEntity) {
        for (MobEffectInstance inst : livingEntity.getActiveEffects()) {
            if (inst.getEffect().value() instanceof ISyncedMobEffect effect) {
                effect.clientTick(livingEntity, inst);
            }
        }
    }
}

public static void handleClientboundFieryExplosion(Vec3 pos, float radius) {
    MinecraftInstanceHelper.ifPlayerPresent(player -> {
        var level = player.level;
        var x = pos.x;
        var y = pos.y;
        var z = pos.z;
        //Blastwave
        level.addParticle(new BlastwaveParticleOptions(new Vector3f(1, .6f, 0.3f), radius + 1), x, y, z, 0, 0, 0);
        //Billowing wave
        int c = (int) (6.28 * radius) * 3;
        float step = 360f / c * Mth.DEG_TO_RAD;
        float speed = (0.06f + 0.01f * radius) * 4f;
        for (int i = 0; i < c; i++) {
            Vec3 vec3 = new Vec3(Mth.cos(step * i), 0, Mth.sin(step * i)).scale(speed);
            Vec3 posOffset = Utils.getRandomVec3(.5f).add(vec3/*.scale(5)*/);
            vec3 = vec3.add(Utils.getRandomVec3(0.01));
            level.addParticle(ParticleHelper.FIERY_SMOKE, x + posOffset.x, y + posOffset.y, z + posOffset.z, vec3.x, vec3.y, vec3.z);
        }
        //Smoke Cloud
        int cloudDensity = 50 + (int) (25 * radius * Math.clamp(radius / 10, 1, 50));
        for (int i = 0; i < cloudDensity; i++) {
            Vec3 posOffset = Utils.getRandomVec3(1).scale(radius * .010f);
            Vec3 motion = posOffset.normalize().scale(speed * .5f);
            posOffset = posOffset.add(motion.scale(Utils.getRandomScaled(1)).normalize());
            motion = motion.add(Utils.getRandomVec3(speed * .2f * (i + cloudDensity) / (float) cloudDensity));
            level.addParticle(ParticleHelper.FIERY_SMOKE, x + posOffset.x, y + posOffset.y, z + posOffset.z, motion.x, motion.y, motion.z);
        }
        int fireDensity = 50 + (int) (25 * radius);
        //Fire Cloud
        for (int i = 0; i < fireDensity; i += 2) {
            Vec3 posOffset = Utils.getRandomVec3(1).scale(radius * .4f);
            Vec3 motion = posOffset.normalize().scale(speed * .5f);
            motion = motion.add(Utils.getRandomVec3(0.25));
            level.addParticle(ParticleHelper.EMBERS, true, x + posOffset.x, y + posOffset.y, z + posOffset.z, motion.x, motion.y, motion.z);
            level.addParticle(ParticleHelper.FIRE, x + posOffset.x * .5f, y + posOffset.y * .5f, z + posOffset.z * .5f, motion.x, motion.y, motion.z);
        }
        //Sparks
        for (int i = 0; i < fireDensity; i += 2) {
            Vec3 posOffset = Utils.getRandomVec3(radius).scale(.2f);
            Vec3 motion = posOffset.normalize().scale(0.8);
            motion = motion.add(Utils.getRandomVec3(0.18));
            level.addParticle(ParticleHelper.FIERY_SPARKS, x + posOffset.x * .5f, y + posOffset.y * .5f, z + posOffset.z * .5f, motion.x, motion.y, motion.z);
        }
    });
}

public void tick() {
    super.tick();
    travel();
    if (level.isClientSide) {
        Vec3 motion = Utils.getRandomVec3(0.08);
        Vec3 movement = getDeltaMovement();
        level.addParticle(ParticleHelper.SOUL_FIRE, getX() - movement.x, getY() + 2 - movement.y, getZ() - movement.z, motion.x, motion.y, motion.z);
    }
    if (getFuse() >= 0) {
        int fuse = getFuse();
        int fuseProgress = getFuseProgressTicks();
        if (isPastChargePhase() && tickCount % 8 == 0) {
            float pitch = Mth.lerp(fuseProgress / (float) fuse, 0.5f, 2f);
            this.playSound(SoundRegistry.SCORCH_PREPARE.get(), 2 + pitch, pitch);
        }
        if (fuseProgress == fuse - 20) {
            this.playSound(SoundRegistry.HEAT_SURGE_PREPARE.get(), 4, 1);
        }
        if (!level.isClientSide && fuseProgress >= fuse) {
            doExplosion();
        }
    }
}

private void doExplosion() {
    Entity owner = getOwner();
    var source = new DamageSource(level.damageSources().damageTypes.getHolderOrThrow(ISSDamageTypes.FIRE_MAGIC), owner);
    var explosionRadiusSqr = radius * radius;
    var entities = level.getEntities(this, this.getBoundingBox().inflate(radius));
    Vec3 losPoint = Utils.raycastForBlock(level, this.position(), this.position().add(0, 1, 0), ClipContext.Fluid.NONE).getLocation();
    float baseDamage = this.damage;
    for (Entity entity : entities) {
        double distanceSqr = entity.distanceToSqr(this.position());
        if (!(entity instanceof OminousFireOrbEntity) && distanceSqr < explosionRadiusSqr && entity.canBeHitByProjectile() && !DamageSources.isFriendlyFireBetween(owner, entity) && Utils.hasLineOfSight(level, losPoint, entity.getBoundingBox().getCenter(), true)) {
            double p = (1 - distanceSqr / explosionRadiusSqr);
            float damage = (float) (baseDamage * p);
            if (entity.hurt(source, damage) && entity instanceof LivingEntity livingVictim) {
                ImmolateEffect.addImmolateStack(livingVictim, owner);
            }
        }
    }
    PacketDistributor.sendToPlayersTrackingEntity(this, new FieryExplosionParticlesPacket(this.getBoundingBox().getCenter(), radius));
    CameraShakeManager.addCameraShake(new CameraShakeData(level,20 + (int) radius / 3, this.position(), this.radius + 15));
    level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.GENERIC_EXPLODE.value(), this.getSoundSource(), 4.0F, (1.0F + (level.random.nextFloat() - level.random.nextFloat()) * 0.2F) * 0.7F);
    discard();
}

public Entity getOwner() {
    if (this.cachedOwner != null && !this.cachedOwner.isRemoved()) {
        return this.cachedOwner;
    } else if (this.ownerUUID != null && this.level() instanceof ServerLevel serverlevel) {
        this.cachedOwner = serverlevel.getEntity(this.ownerUUID);
        return this.cachedOwner;
    } else {
        return null;
    }
}
